alter table public.academic_years add column available boolean not null default true;
alter table public.terms add column available boolean not null default true;
alter table public.stages add column available boolean not null default true;
alter table public.grades add column available boolean not null default true;
alter table public.sections add column term_id uuid references public.terms(id);
create table public.org_academic_catalog(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.organizations(id), kind text not null, name text not null, stage text, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
grant select,insert,update,delete on public.org_academic_catalog to authenticated; grant all on public.org_academic_catalog to service_role;
alter table public.org_academic_catalog enable row level security;
create policy org_academic_read on public.org_academic_catalog for select to authenticated using(is_org_owner(org_id) or exists(select 1 from memberships m where m.user_id=auth.uid() and m.org_id=org_academic_catalog.org_id and m.is_active and not m.branch_suspended));
create policy org_academic_insert on public.org_academic_catalog for insert to authenticated with check(is_org_owner(org_id));
create policy org_academic_update on public.org_academic_catalog for update to authenticated using(is_org_owner(org_id)) with check(is_org_owner(org_id));
create policy org_academic_delete on public.org_academic_catalog for delete to authenticated using(is_org_owner(org_id));
create trigger org_academic_touch before update on public.org_academic_catalog for each row execute function public.touch_updated_at();
create or replace function public.academic_allocate(_school uuid,_kind text,_name text,_start date default null,_end date default null,_parent uuid default null) returns uuid language plpgsql security invoker set search_path=public as $$ declare i uuid; _org uuid:=school_org(_school); _stage text; begin
if not is_org_owner(_org) then raise exception 'غير مصرح'; end if;
if _kind='grade' then select name into _stage from stages where id=_parent and school_id=_school; end if;
if not exists(select 1 from academic_catalog c where c.kind=_kind and c.name=_name and (_kind<>'grade' or c.stage=_stage)) and not exists(select 1 from org_academic_catalog c where c.org_id=_org and c.kind=_kind and c.name=_name and (_kind<>'grade' or c.stage=_stage)) then raise exception 'المحدد غير معتمد في قائمة المؤسسة'; end if;
if _kind='year' then if _start is null or _end is null or _end<=_start then raise exception 'حدد تواريخ العام الصحيحة'; end if; insert into academic_years(school_id,name,start_date,end_date) values(_school,_name,_start,_end) on conflict(school_id,name) do update set available=true returning id into i;
elsif _kind='stage' then insert into stages(school_id,name) values(_school,_name) on conflict(school_id,name) do update set available=true returning id into i;
elsif _kind='grade' then if _stage is null then raise exception 'اختر مرحلة من الفرع'; end if; insert into grades(school_id,stage_id,name) values(_school,_parent,_name) on conflict(stage_id,name) do update set available=true returning id into i;
elsif _kind='term' then if not exists(select 1 from academic_years where id=_parent and school_id=_school) then raise exception 'اختر عام الفرع'; end if; insert into terms(school_id,year_id,name,start_date,end_date) values(_school,_parent,_name,_start,_end) on conflict(year_id,name) do update set available=true returning id into i;
else raise exception 'نوع غير صالح'; end if; return i; end $$;
revoke all on function public.academic_allocate(uuid,text,text,date,date,uuid) from public,anon; grant execute on function public.academic_allocate(uuid,text,text,date,date,uuid) to authenticated,service_role;
create or replace function public._academic_section_guard() returns trigger language plpgsql set search_path=public as $$ declare s uuid; begin s:=case when tg_op='DELETE' then old.school_id else new.school_id end; if not _section_vice_ok(s) then raise exception 'تكوين الشعب من صلاحية الوكيل ضمن فرعه'; end if; if tg_op='DELETE' then return old; end if; if tg_op='UPDATE' and new.school_id<>old.school_id then raise exception 'لا يسمح بنقل الشعبة إلى فرع آخر'; end if; if not exists(select 1 from grades g join stages st on st.id=g.stage_id where g.id=new.grade_id and g.school_id=s and st.school_id=s and g.available and st.available) or not exists(select 1 from academic_years y where y.id=new.year_id and y.school_id=s and y.available) then raise exception 'الصف أو العام غير متاح للفرع'; end if; if new.term_id is null and (tg_op='INSERT' or old.term_id is not null) then raise exception 'اختر الفصل الدراسي'; end if; if new.term_id is not null and not exists(select 1 from terms t where t.id=new.term_id and t.school_id=s and t.year_id=new.year_id and t.available) then raise exception 'الفصل غير متاح للعام أو الفرع'; end if; return new; end $$;